// Uploads must survive a 429: the multipart body is buffered and replayable,
// so the retry transport can resend it (https://github.com/juhokoskela/pipedrive-go
// issue: file uploads fail to retry).
func TestFilesService_AddRetriesAfterRateLimit(t *testing.T) {
	t.Parallel()

	content := []byte("retryable-upload")
	var calls int
	client := newTestClientWithConfig(t, pipedrive.Config{
		RetryPolicy: &pipedrive.RetryPolicy{
			MaxAttempts: 3,
			BaseDelay:   time.Millisecond,
			MaxDelay:    time.Millisecond,
			Jitter:      func(d time.Duration) time.Duration { return d },
		},
	}, func(w http.ResponseWriter, r *http.Request) {
		calls++
		if calls == 1 {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusTooManyRequests)
			_, _ = w.Write([]byte(`{"error":"rate limited"}`))
			return
		}

		fileName, fields := parseMultipartRequest(t, r)
		if fileName != "upload.txt" {
			t.Fatalf("unexpected file name on retry: %s", fileName)
		}
		if !bytes.Equal(fields["file"], content) {
			t.Fatalf("replayed file content mismatch: %q", fields["file"])
		}
		if got := fields["deal_id"]; got != "3" {
			t.Fatalf("unexpected deal_id on retry: %q", got)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	file, err := client.Files.Add(
		context.Background(),
		"upload.txt",
		bytes.NewReader(content),
		WithFileDealID(DealID(3)),
	)
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if calls != 2 {
		t.Fatalf("expected 2 attempts, got %d", calls)
	}
	if file.ID != 12 {
		t.Fatalf("unexpected file: %#v", file)
	}
}

func parseMultipartRequest(t *testing.T, r *http.Request) (string, map[string][]byte) {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if mediaType != "multipart/form-data" {
		t.Fatalf("unexpected media type: %s", mediaType)
	}

	var fileName string
	fields := map[string][]byte{}
	reader := multipart.NewReader(r.Body, params["boundary"])
	for {
		part, err := reader.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		value, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part value: %v", err)
		}
		if part.FileName() != "" && fileName == "" {
			fileName = part.FileName()
		}
		fields[part.FormName()] = value
	}
	return fileName, fields
}

