	if fileName == "" {
		return nil, fmt.Errorf("file name is required")
	}
	if content == nil {
		return nil, fmt.Errorf("file content is required")
	}
	cfg := newFilesOptions(opts)

	contentType, body, err := multipartbody.NewFile("file", fileName, content, cfg.payload.multipartFields()...)
	if err != nil {
		return nil, err
