	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, path, cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing person picture data in response")
	}
	return payload.Data, nil
}

