// AddPicture uploads a picture for a person as a multipart/form-data body.
// The content is buffered so the request body is replayable and retried on
// 429/5xx like every other call.
func (s *PersonsService) AddPicture(ctx context.Context, id PersonID, fileName string, content io.Reader, opts ...PersonsOption) (map[string]any, error) {
	if err := validateID(id, "person id"); err != nil {
		return nil, err
	}
	if fileName == "" {
		return nil, fmt.Errorf("file name is required")
	}
	if content == nil {
		return nil, fmt.Errorf("picture content is required")
	}
	cfg := newPersonsOptions(opts)
	path := fmt.Sprintf("/persons/%d/picture", id)

	contentType, body, err := multipartbody.NewFile("file", fileName, content, cfg.pictureCrop.multipartFields()...)
	if err != nil {
		return nil, err
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data map[string]any `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, path, cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing person picture data in response")
	}
	return payload.Data, nil
}

